<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\{HttpException,Request};
use Sentinel\Tests\FieldFixture;

final class OperationalReadinessTest extends TestCase
{
    private const PNG='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aR1cAAAAASUVORK5CYII=';
    private function rejects(callable $fn,int $status):void {try{$fn();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode(),$e->getMessage());}}
    private function keyInput():array{return ['site_id'=>1,'asset_code'=>'KEY-001','asset_name'=>'Main gate key','asset_type'=>'KEY'];}
    private function signed(int $revision):array{return ['expected_revision'=>$revision,'signature_base64'=>self::PNG,'notes'=>'Physical handover checked.'];}
    private function procedure():array{return ['site_id'=>1,'expected_revision'=>0,'title'=>'Evacuation','steps'=>['Contact control room','Move to assembly point'],'emergency_contacts'=>'Control room radio channel 1','assembly_point'=>'North assembly point'];}
    private function roster($db):array {
        foreach(['position_id INTEGER','assignment_status TEXT','deleted_at TEXT']as$c)$db->execute('ALTER TABLE employee_assignments ADD COLUMN '.$c);
        $db->execute('CREATE TABLE positions(position_id INTEGER PRIMARY KEY,company_id INTEGER,position_category TEXT,position_status TEXT,deleted_at TEXT)');$db->execute("INSERT INTO positions VALUES(1,101,'GUARD','ACTIVE',NULL)");$db->execute("INSERT INTO employee_assignments VALUES(1,101,1,1,'ACTIVE',NULL),(2,101,2,1,'ACTIVE',NULL)");
        $db->execute('ALTER TABLE sites ADD COLUMN latitude NUMERIC');$db->execute('ALTER TABLE sites ADD COLUMN longitude NUMERIC');$db->execute('UPDATE sites SET latitude=-29.85,longitude=31.02 WHERE site_id=1');
        $date=gmdate('Y-m-d',time()+86400);$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(1,101,1,1,:start,:end,'ASSIGNED')",['start'=>$date.' 10:00:00','end'=>$date.' 12:00:00']);return ['start'=>$date.' 10:00:00','end'=>$date.' 12:00:00'];
    }
    private function preference():array{return ['employee_id'=>2,'expected_revision'=>0,'max_weekly_minutes'=>2880,'minimum_rest_minutes'=>660,'base_latitude'=>null,'base_longitude'=>null,'max_distance_km'=>200];}
    public function testKeyCustodyRequiresRecipientAcceptanceAndSeparateReturnReceipt():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('key_custody_service');$asset=$s->create($this->keyInput())['id'];$issue=['expected_revision'=>1,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Gate duty'];$loan=$s->issue($asset,$issue)['id'];$this->rejects(fn()=>$s->issue($asset,$issue),409);$this->rejects(fn()=>$s->selfAction($loan,'accept',$this->signed(1)),404);$ctx->setUser('2');$this->rejects(fn()=>$s->selfAction($loan,'accept',[...$this->signed(1),'signature_base64'=>base64_encode('invalid')]),422);$s->selfAction($loan,'accept',$this->signed(1));self::assertSame('ISSUED',$s->mine()[0]['state']);$s->selfAction($loan,'return',$this->signed(2));$this->rejects(fn()=>$s->manageLoan($loan,'receive',$this->signed(3)),403);$db->execute("INSERT INTO users VALUES(4,101,2,'second-account','same-employee@example.test','hash','ACTIVE')");$ctx->setUser('4');$this->rejects(fn()=>$s->manageLoan($loan,'receive',$this->signed(3)),403);$ctx->setUser('1');$s->manageLoan($loan,'receive',$this->signed(3));$row=$s->assets(['site_id'=>1])[0];self::assertSame('AVAILABLE',$row['state']);self::assertSame('RETURNED',$row['loans'][0]['state']);self::assertNotNull($row['loans'][0]['recipient_signature_hash']);self::assertNotNull($row['loans'][0]['return_signature_hash']);self::assertNotNull($row['loans'][0]['receiver_signature_hash']);self::assertCount(4,$s->history($asset));self::assertCount(3,$s->receipt($loan)['signatures']);$db->execute("UPDATE custody_loans SET receiver_signature_hash='corrupted'");$this->rejects(fn()=>$s->receipt($loan),409);self::assertStringNotContainsString(self::PNG,json_encode($row));
    }
    public function testLostKeyCannotBeReissuedUntilRecoveryAndPendingIssueCanBeCancelled():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('key_custody_service');$asset=$s->create($this->keyInput())['id'];$loan=$s->issue($asset,['expected_revision'=>1,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Issue'])['id'];$s->manageLoan($loan,'lost',['expected_revision'=>1,'notes'=>'Card disabled in door system; supervisor notified.']);self::assertSame('LOST',$s->assets(['site_id'=>1])[0]['state']);self::assertSame('LOST_KEY',$db->fetch('SELECT incident_type FROM incidents')['incident_type']);$ctx->setUser('2');$this->rejects(fn()=>$s->selfAction($loan,'accept',$this->signed(2)),409);$ctx->setUser('1');$s->assetAction($asset,['expected_revision'=>3,'action'=>'recover','notes'=>'Recovered and inspected.']);$loan2=$s->issue($asset,['expected_revision'=>4,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Issue again'])['id'];$s->manageLoan($loan2,'cancel',['expected_revision'=>1,'notes'=>'Not required']);self::assertSame('AVAILABLE',$s->assets(['site_id'=>1])[0]['state']);
    }
    public function testKeyScopeTenantValidationAndOverdueFlags():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('key_custody_service');$this->rejects(fn()=>$s->create([...$this->keyInput(),'site_id'=>3]),404);$id=$s->create($this->keyInput())['id'];$this->rejects(fn()=>$s->issue($id,['expected_revision'=>1,'employee_id'=>3,'due_at'=>gmdate('Y-m-d H:i:s',time()+60),'notes'=>'Wrong tenant']),404);$s->issue($id,['expected_revision'=>1,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+60),'notes'=>'Issue']);$db->execute("UPDATE custody_loans SET due_at='2020-01-01 00:00:00'");self::assertTrue($s->assets(['site_id'=>1])[0]['loans'][0]['overdue']);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$s->history($id),404);self::assertSame([],$s->mine());
    }
    public function testReplacementApprovalRecomputesEligibilityAndRetainsReliefHistory():void {
        [$app,$db]=$f=FieldFixture::create();$times=$this->roster($db);$s=$app->container()->make('replacement_suggestion_service');$data=$s->suggest('1');self::assertSame(['2'],array_column($data['eligible'],'employee_id'));self::assertFalse($data['eligible'][0]['distance_known']);$leave=$app->container()->make('availability_service');$absence=$leave->request(['employee_id'=>2,'request_type'=>'LEAVE','starts_at'=>$times['start'],'ends_at'=>$times['end'],'reason'=>'Leave'])['id'];$leave->review($absence,'approve',['expected_revision'=>1,'notes'=>'Approved']);$this->rejects(fn()=>$s->approve('1',['expected_employee_id'=>1,'replacement_employee_id'=>2,'reason'=>'Select stale candidate']),409);$leave->review($absence,'cancel',['expected_revision'=>2,'notes'=>'Withdrawn']);self::assertTrue($s->approve('1',['expected_employee_id'=>1,'replacement_employee_id'=>2,'reason'=>'Manager checked availability'])['assigned']);self::assertSame(1,(int)$db->fetch('SELECT previous_employee_id FROM shift_relief_history')['previous_employee_id']);
    }
    public function testReplacementTrainingHoursRestAndDistanceAreExplained():void {
        [$app,$db]=FieldFixture::create();$times=$this->roster($db);$s=$app->container()->make('replacement_suggestion_service');$db->execute("INSERT INTO training_competencies(company_id,competency_code,competency_name) VALUES(101,'FIRE','Fire training')");$db->execute('INSERT INTO site_training_requirements(company_id,site_id,competency_id) VALUES(101,1,1)');self::assertContains('MISSING_VALID_TRAINING',$s->suggest('1')['excluded'][0]['reasons']);$db->execute("INSERT INTO employee_training(company_id,employee_id,competency_id,reference_number,valid_from,valid_until,verified_at) VALUES(101,2,1,'REF','2020-01-01','2030-01-01','2026-01-01')");$s->preference([...$this->preference(),'max_weekly_minutes'=>60]);self::assertContains('WEEKLY_LIMIT',$s->suggest('1')['excluded'][0]['reasons']);$s->preference([...$this->preference(),'expected_revision'=>1,'base_latitude'=>-33.9,'base_longitude'=>18.4,'max_distance_km'=>10]);self::assertContains('DISTANCE_LIMIT',$s->suggest('1')['excluded'][0]['reasons']);$s->preference([...$this->preference(),'expected_revision'=>2,'base_latitude'=>-29.85,'base_longitude'=>31.02]);self::assertSame(0.0,$s->suggest('1')['eligible'][0]['straight_line_km']);$date=substr($times['start'],0,10);$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(2,101,2,1,:start,:end,'ASSIGNED')",['start'=>$date.' 06:00:00','end'=>$date.' 08:00:00']);self::assertContains('REST_LIMIT',$s->suggest('1')['excluded'][0]['reasons']);
    }
    public function testEmergencyVersionRollCallAndStepsCannotBeSkipped():void {
        [$app,$db]=$f=FieldFixture::create();$s=$app->container()->make('emergency_procedure_service');$p=$s->publish($this->procedure())['id'];$id=$s->start(['procedure_id'=>$p,'exercise_type'=>'EMERGENCY','title'=>'Actual evacuation','participants'=>['Guard E1','Visitor V1']])['id'];$this->rejects(fn()=>$s->finish($id,['expected_revision'=>1,'debrief'=>'Attempt early close']),409);$s->publish([...$this->procedure(),'expected_revision'=>1,'steps'=>['New procedure step']]);$this->rejects(fn()=>$s->start(['procedure_id'=>$p,'exercise_type'=>'DRILL','title'=>'Stale','participants'=>['Guard']]),409);$data=$s->workspace(['site_id'=>1]);$event=$data['exercises'][0];self::assertCount(2,$event['procedure']['steps']);foreach($event['roll_call']as$r)$s->rollCall((string)$r['participant_id'],['expected_revision'=>1,'state'=>'SAFE','notes'=>'At assembly point']);$s->completeStep($id,['step_number'=>1,'notes'=>'Control contacted']);$s->completeStep($id,['step_number'=>2,'notes'=>'Assembly complete']);$this->rejects(fn()=>$s->completeStep($id,['step_number'=>3,'notes'=>'Not in original version']),422);$this->rejects(fn()=>$s->finish($id,['expected_revision'=>1,'debrief'=>'Stale snapshot']),409);self::assertSame('CLOSED',$s->finish($id,['expected_revision'=>5,'debrief'=>'All listed people safe.'])['state']);$this->rejects(fn()=>$s->rollCall('1',['expected_revision'=>2,'state'=>'MISSING','notes'=>'After closed']),409);
    }
    public function testReplacementWeeklyLimitChecksBothSidesOfSundayNight():void {
        [$app,$db]=FieldFixture::create();$this->roster($db);$s=$app->container()->make('replacement_suggestion_service');$s->preference([...$this->preference(),'max_weekly_minutes'=>60,'minimum_rest_minutes'=>0]);$start=(new \DateTimeImmutable('next sunday',new \DateTimeZone('UTC')))->setTime(23,0);$end=$start->modify('+2 hours');$db->execute('UPDATE shift_assignments SET shift_start_at=:start,shift_end_at=:end WHERE shift_assignment_id=1',['start'=>$start->format('Y-m-d H:i:s'),'end'=>$end->format('Y-m-d H:i:s')]);$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(2,101,2,1,:start,:end,'ASSIGNED')",['start'=>$end->modify('+2 hours')->format('Y-m-d H:i:s'),'end'=>$end->modify('+150 minutes')->format('Y-m-d H:i:s')]);self::assertSame([],$s->suggest('1')['eligible']);self::assertContains('NEXT_WEEK_LIMIT',$s->suggest('1')['excluded'][0]['reasons']);
    }
    public function testDrillClosesWithFindingsAndNeverClaimsMissingPeopleSafe():void {
        [$app,$db]=FieldFixture::create();$s=$app->container()->make('emergency_procedure_service');$p=$s->publish($this->procedure())['id'];$id=$s->start(['procedure_id'=>$p,'exercise_type'=>'DRILL','title'=>'Practice','participants'=>['Visitor']])['id'];$result=$s->finish($id,['expected_revision'=>1,'debrief'=>'Missing roll-call practice identified.']);self::assertSame('CLOSED_WITH_FINDINGS',$result['state']);self::assertSame(1,$result['unaccounted_count']);$this->rejects(fn()=>$s->workspace(['site_id'=>3]),404);
    }
    public function testReviewedTranslationsFallBackWhenSourceChanges():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('workflow_language_service');$id=$app->container()->make('site_assurance_service')->publishInstructions(['site_id'=>1,'expected_revision'=>0,'title'=>'Gate instructions','instructions'=>'Keep gate closed.','emergency_contacts'=>'Control room'])['id'];$s->setPreference(['language_code'=>'zu']);$source=$s->read(['entity_kind'=>'INSTRUCTION','entity_id'=>$id]);self::assertTrue($source['fallback']);$translation=['title'=>'Imiyalelo yesango','instructions'=>'Gcina isango livaliwe.','emergency_contacts'=>'Igumbi lokulawula'];$s->publish(['entity_kind'=>'INSTRUCTION','entity_id'=>$id,'language_code'=>'zu','expected_source_hash'=>$source['source_hash'],'expected_revision'=>0,'content'=>$translation]);$read=$s->read(['entity_kind'=>'INSTRUCTION','entity_id'=>$id]);self::assertSame('zu',$read['display_language']);self::assertSame($translation,$read['content']);$db->execute("UPDATE site_instruction_versions SET instructions='Updated safety instructions.'");self::assertTrue($s->read(['entity_kind'=>'INSTRUCTION','entity_id'=>$id])['fallback']);$this->rejects(fn()=>$s->publish(['entity_kind'=>'INSTRUCTION','entity_id'=>$id,'language_code'=>'zu','expected_source_hash'=>$source['source_hash'],'expected_revision'=>1,'content'=>$translation]),409);$this->rejects(fn()=>$s->setPreference(['language_code'=>'unknown']),422);
    }
    public function testInspectionTranslationsPreserveKeysAndDoNotAlterRequiredAnswers():void {
        [$app,$db]=FieldFixture::create();$forms=$app->container()->make('inspection_forms_service');$id=$forms->publish(['site_id'=>1,'form_code'=>'GATE','expected_revision'=>0,'title'=>'Gate check','fields'=>[['key'=>'gate','label'=>'Gate secure','type'=>'CHECK','required'=>true,'photo_required'=>false,'followup_on_fail'=>true]]])['id'];$s=$app->container()->make('workflow_language_service');$source=$s->read(['entity_kind'=>'INSPECTION_FORM','entity_id'=>$id]);$base=['entity_kind'=>'INSPECTION_FORM','entity_id'=>$id,'language_code'=>'af','expected_source_hash'=>$source['source_hash'],'expected_revision'=>0];$this->rejects(fn()=>$s->publish($base+['content'=>['title'=>'Hekkontrole','labels'=>['wrong'=>'Hek veilig']]]),422);$s->publish($base+['content'=>['title'=>'Hekkontrole','labels'=>['gate'=>'Hek veilig']]]);$s->setPreference(['language_code'=>'af']);$f=$forms->templates(['site_id'=>1])[0];self::assertSame('Hekkontrole',$f['title']);$fields=json_decode($f['fields_json'],true);self::assertSame('gate',$fields[0]['key']);self::assertTrue($fields[0]['required']);self::assertSame('Hek veilig',$fields[0]['label']);
    }
    public function testNotificationTranslationCannotReadAnotherRecipientsNotification():void {
        [$app,$db,$ctx]=FieldFixture::create();$db->execute("INSERT INTO notifications(company_id,recipient_user_id,event_type,title,message) VALUES(101,2,'TEST','Notice','Report received.')");$s=$app->container()->make('workflow_language_service');$this->rejects(fn()=>$s->read(['entity_kind'=>'NOTIFICATION','entity_id'=>1]),404);$source=$s->reviewSource(['entity_kind'=>'NOTIFICATION','entity_id'=>1,'language_code'=>'af']);$s->publish(['entity_kind'=>'NOTIFICATION','entity_id'=>1,'language_code'=>'af','expected_source_hash'=>$source['source_hash'],'expected_revision'=>0,'content'=>['title'=>'Kennisgewing','message'=>'Verslag ontvang.']]);$ctx->setUser('2');$s->setPreference(['language_code'=>'af']);self::assertCount(1,$s->notifications());self::assertSame('Verslag ontvang.',$app->container()->make('alert_notification_service')->inbox()[0]['message']);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$s->read(['entity_kind'=>'NOTIFICATION','entity_id'=>1]),404);
    }
    public function testBrandingRevisionUsageAndPlanRequestsCannotSelfUpgrade():void {
        [$app,$db]=FieldFixture::create();$db->execute('CREATE TABLE company_subscriptions(company_id INTEGER,plan_code TEXT,subscription_status TEXT,trial_ends_at TEXT,current_period_ends_at TEXT)');$db->execute("INSERT INTO company_subscriptions VALUES(101,'ESSENTIAL','ACTIVE',NULL,NULL)");$s=$app->container()->make('company_workspace_service');$body=['expected_revision'=>0,'display_name'=>'Example Security','primary_color'=>'#123456','support_contact'=>'Control room ext 100','logo_base64'=>self::PNG];$this->rejects(fn()=>$s->saveBranding([...$body,'primary_color'=>'red;position:absolute']),422);$s->saveBranding($body);self::assertSame('Example Security',$s->branding()['display_name']);$this->rejects(fn()=>$s->saveBranding($body),409);$data=$s->overview();self::assertSame(2,$data['usage']['users']);self::assertSame(2,$data['usage']['sites']);self::assertSame(28,$data['remaining']['users']);$s->requestPlan(['target_plan'=>'ENTERPRISE','notes'=>'Please quote the upgrade.']);self::assertSame('ESSENTIAL',$db->fetch('SELECT plan_code FROM company_subscriptions')['plan_code']);$this->rejects(fn()=>$s->requestPlan(['target_plan'=>'FREE','notes'=>'Second request']),409);$s->cancelPlan('1');self::assertSame('CANCELLED',$s->overview()['change_requests'][0]['state']);$s->completeCheck(['check_code'=>'BACKUP','evidence_reference'=>'Restore test 123']);self::assertCount(1,$s->overview()['completed_checks']);$s->reopenCheck('BACKUP');self::assertSame([],$s->overview()['completed_checks']);
    }
    public function testRestrictedRoleHasScopedKeysAndEmergencyButNoCompanyOrWorkforceDirectory():void {
        [$app,$db,$ctx]=FieldFixture::create();$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$scope=$app->container()->make('site_access_service');$scope->restrictRole(['role_id'=>2,'restricted'=>true]);$scope->grant(['user_id'=>2,'site_id'=>2]);$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$ctx->setUser('2');$auth=$app->container()->make('authorization_service');self::assertTrue($auth->isAllowed('2','key_register.view'));self::assertTrue($auth->isAllowed('2','emergency_procedures.manage'));self::assertFalse($auth->isAllowed('2','replacement_suggestions.view'));self::assertFalse($auth->isAllowed('2','company_workspace.view'));self::assertFalse($auth->isAllowed('2','workflow_languages.manage'));$this->rejects(fn()=>$app->container()->make('key_custody_service')->assets(['site_id'=>1]),404);$this->rejects(fn()=>$app->container()->make('emergency_procedure_service')->publish($this->procedure()),404);
    }
    public function testAuditFailureRollsBackKeyIssueAndEmergencyStart():void {
        [$app,$db]=FieldFixture::create();$keys=$app->container()->make('key_custody_service');$id=$keys->create($this->keyInput())['id'];$emergency=$app->container()->make('emergency_procedure_service');$p=$emergency->publish($this->procedure())['id'];$db->execute("CREATE TRIGGER reject_readiness_audit BEFORE INSERT ON audit_logs BEGIN SELECT RAISE(ABORT,'audit unavailable');END");foreach([fn()=>$keys->issue($id,['expected_revision'=>1,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Issue']),fn()=>$emergency->start(['procedure_id'=>$p,'exercise_type'=>'DRILL','title'=>'Practice','participants'=>['Guard']])]as$fn){try{$fn();self::fail('Expected audit failure');}catch(\PDOException){self::assertTrue(true);}}self::assertSame('AVAILABLE',$keys->assets(['site_id'=>1])[0]['state']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM custody_loans')['n']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM emergency_exercises')['n']);
    }
}
